  resources: Record<string, ResourceOutputSpec> | undefined,
  dataOutputOverrides:
    | ReadonlyArray<{ specName: string; vaultName?: string }>
    | undefined,
  vaults: SensitiveOutputVaultConfig,
): string[] {
  return [
    ...new Set(
      sensitiveOutputTargets(resources, dataOutputOverrides, vaults).map((t) =>
