        "Get moderator add/remove events for the configured channel (requires broadcaster authorization; uses legacy endpoint, may return empty on newer channels)",
      arguments: z.object({}),
      execute: async (_args: Record<string, never>, context: MethodContext) => {
        const startMs = Date.now();
        const { channel, hasBroadcasterAuth } = context.globalArgs;

        if (!hasBroadcasterAuth) {
          throw new Error(
            "get_mod_events requires broadcaster authorization. " +
              "Set hasBroadcasterAuth=true if the broadcaster has OAuth'd this app.",
          );
        }

        const creds = credsFrom(context.globalArgs);
        const broadcasterId = await getBroadcasterId(creds, channel);

        const raw = await helixApiPaginated<{
          event_type: string;
          event_timestamp: string;
          event_data: {
            user_id: string;
            user_login: string;
            broadcaster_login: string;
          };
        }>(
          creds,
          `/moderation/moderators/events?broadcaster_id=${broadcasterId}`,
        );

        const events = raw.data.map((e) => ({
          eventType: e.event_type,
          eventTimestamp: e.event_timestamp,
          userId: e.event_data.user_id,
          userLogin: e.event_data.user_login,
          channelLogin: e.event_data.broadcaster_login,
        }));

        const handle = await context.writeResource("mod-events", channel, {
          channel,
          events,
          count: events.length,
          truncated: raw.truncated,
          fetchedAt: new Date().toISOString(),
          durationMs: Date.now() - startMs,
          collectedBy: EXTENSION_NAME,
        });

        context.logger.info("Found {count} mod events in {channel}", {
          count: events.length,
          channel,
        });
        return { dataHandles: [handle] };
      },
    },
  },
